276	    /**
277	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
278	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
279	     * the request body already rejects null and empty values, but permits whitespace-only strings
280	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
281	     * that gap so every required field must carry a non-blank value.
282	     *
283	     * @param ownerFieldsDto the submitted owner fields
284	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
285	     */
286	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
287	        List<String> missing = new ArrayList<>();
288	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
289	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
290	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
291	            missing.add("address");
292	        }
293	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
294	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
295	        if (!missing.isEmpty()) {
296	            throw new InvalidOwnerFieldsException(missing);
297	        }
298	    }
