300	    /**
301	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
302	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
303	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
304	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
305	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
306	     * {@link PostcodeValidator}.
307	     *
308	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
309	     *                       {@link #rejectBlankOwnerFields} having already run)
310	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
311	     */
312	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
313	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
314	            throw new InvalidOwnerFieldsException(List.of("postcode"));
