328	    /**
329	     * Normalizes the submitted address on create to its canonical form (see
330	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
331	     * stored and returned, and the form every later address comparison (the required-field check,
332	     * household duplicate detection and the shared household id) is judged on. The structured fields
333	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
334	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
335	     * derived from them when a structured {@code addressLine1} is present, falling back to the
336	     * normalized flat {@code address} otherwise. Any absent field is left absent so
337	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
338	     * after normalization likewise reduces to the empty string and is rejected there.
339	     *
340	     * @param ownerFieldsDto the submitted owner fields
341	     */
342	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
343	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
344	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
345	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
346	        ownerFieldsDto.setAddressLine1(addressLine1);
347	        ownerFieldsDto.setAddressLine2(addressLine2);
348	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
349	    }
350	
351	    /**
352	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
353	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
354	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
355	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
356	     * is the single value every later reader of the address (the required-field check, household
357	     * duplicate detection and the shared household id) is judged on.
358	     *
359	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
360	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
361	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
362	     * @return the composed flat address, or {@code null} when no address form was supplied
363	     */
364	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
365	        if (isBlank(addressLine1)) {
366	            return flatAddress;
367	        }
368	        if (isBlank(addressLine2)) {
369	            return addressLine1;
370	        }
371	        return addressLine1 + " " + addressLine2;
372	    }
