374	    /**
375	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
376	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
377	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
378	     * {@code 400 Bad Request}.
379	     *
380	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
381	     *                       {@link #rejectBlankOwnerFields} having already run)
382	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
383	     */
384	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
385	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
386	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
387	        ownerFieldsDto.setTelephone(normalized);
388	    }
