390	    /**
391	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
392	     * untouched (email is optional). When present it is reduced to its canonical form (see
393	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
394	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
395	     *
396	     * @param ownerFieldsDto the submitted owner fields
397	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
398	     *                                     or its domain is on the disposable-domain blocklist
399	     */
400	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
401	        String email = ownerFieldsDto.getEmail();
402	        if (email == null || email.isBlank()) {
403	            return;
404	        }
405	        String normalized = EmailNormalizer.normalize(email)
406	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
407	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
408	            throw new InvalidOwnerFieldsException(List.of("email"));
409	        }
410	        ownerFieldsDto.setEmail(normalized);
411	    }
