413	    /**
414	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
415	     * duplicate detection is now expressed through the single derived {@code identityKey}
416	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
417	     * which replaces the previously separate telephone, email and household checks. Two owners denote
418	     * the same person when their identities collide on the telephone - the identity's distinguishing
419	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
420	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
421	     * same household with different telephones have different identities and are both allowed; an email
422	     * or a household on its own no longer makes a duplicate.
423	     *
424	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
425	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
426	     * @param householdId    the household id derived for the owner being created (see
427	     *                       {@link HouseholdNormalizer#toHouseholdId})
428	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
429	     */
430	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
431	        String identityKey = OwnerIdentity.identityKey(
432	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
433	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
434	        boolean inUse = this.clinicService.findAllOwners().stream()
435	            .map(Owner::getTelephone)
436	            .filter(Objects::nonNull)
437	            .map(TelephoneNormalizer::toComparisonKey)
438	            .anyMatch(telephoneKey::equals);
439	        if (inUse) {
440	            throw new DuplicateOwnerIdentityException(identityKey);
441	        }
442	    }
