445	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
446	     * both match the submitted values, compared case-insensitively. The count reflects only owners
447	     * already persisted at the time of the create, so the owner being created is never included.
448	     *
449	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
450	     *                  having already run)
451	     * @param lastName  the submitted last name (non-blank here)
452	     * @return the number of existing owners sharing the same first and last name
453	     */
454	    private int countNamesakes(String firstName, String lastName) {
455	        return (int) this.clinicService.findAllOwners().stream()
456	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
457	                && lastName.equalsIgnoreCase(owner.getLastName()))
458	            .count();
