462	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
463	     * whose stored {@code householdId} equals the value derived for the owner being created. The
464	     * count reflects only owners already persisted at the time of the create, so the owner being
465	     * created is never included; callers add one to obtain the household size after this create.
466	     *
467	     * @param householdId the household identifier derived for the owner being created (see
468	     *                    {@link HouseholdNormalizer#toHouseholdId})
469	     * @return the number of existing owners already sharing that household
470	     */
471	    private int countHouseholdMembers(String householdId) {
472	        if (householdId == null) {
473	            return 0;
474	        }
475	        return (int) this.clinicService.findAllOwners().stream()
476	            .map(Owner::getHouseholdId)
477	            .filter(householdId::equals)
478	            .count();
