494	    /**
495	     * Derives the household id an owner should carry from its submitted fields (see
496	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
497	     * household id, so routing them through this single method keeps them agreed on which of the
498	     * owner's fields key the household.
499	     *
500	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
501	     *                       {@link #rejectBlankOwnerFields} having already run on create)
502	     * @return the owner's household id
503	     */
504	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
505	        return HouseholdNormalizer.toHouseholdId(
506	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
507	    }
