509	    /**
510	     * Rejects creating an owner that would join an existing household without declaring itself a
511	     * member. The household is keyed on (last name, postcode) through the derived {@code householdId}
512	     * (see {@link HouseholdNormalizer#toHouseholdId}), so a second owner sharing an existing owner's
513	     * last name and postcode denotes the same household. Such a create is reported as a {@code 409
514	     * Conflict} unless it opts in with {@code sharesHousehold}, in which case it is accepted as a
515	     * declared household member. Only owners already persisted (before this create) are considered.
516	     *
517	     * @param householdId     the household id derived for the owner being created
518	     * @param sharesHousehold whether the request opted in to sharing a household
519	     * @throws DuplicateOwnerHouseholdException if the household already exists and the request did not
520	     *                                          opt in with {@code sharesHousehold}
521	     */
522	    private void rejectHouseholdDuplicate(String householdId, boolean sharesHousehold) {
523	        if (sharesHousehold || householdId == null) {
524	            return;
525	        }
526	        boolean householdExists = this.clinicService.findAllOwners().stream()
527	            .map(Owner::getHouseholdId)
528	            .anyMatch(householdId::equals);
529	        if (householdExists) {
530	            throw new DuplicateOwnerHouseholdException(householdId);
531	        }
532	    }
