534	    /**
535	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
536	     * is none. The create has already cleared the hard-duplicate identity check
537	     * ({@link #rejectDuplicateIdentity}), so it is not an exact match of any existing owner; it is a
538	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code lastName}
539	     * (compared case-insensitively) and {@code postcode} while carrying a different normalized
540	     * telephone. The oldest such owner (the earliest persisted) is returned so the flag points at the
541	     * original record; owners with no postcode never match, since a shared postcode is required.
542	     *
543	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
544	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
545	     *         duplicate
546	     */
547	    private Integer findPossibleDuplicate(Owner owner) {
548	        String postcode = owner.getPostcode();
549	        if (postcode == null) {
550	            return null;
551	        }
552	        String telephoneKey = TelephoneNormalizer.toComparisonKey(owner.getTelephone());
553	        return this.clinicService.findAllOwners().stream()
554	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
555	            .filter(existing -> postcode.equals(existing.getPostcode()))
556	            .filter(existing -> existing.getTelephone() != null
557	                && !telephoneKey.equals(TelephoneNormalizer.toComparisonKey(existing.getTelephone())))
558	            .map(Owner::getId)
559	            .filter(Objects::nonNull)
560	            .min(Integer::compareTo)
561	            .orElse(null);
562	    }
