564	    /**
565	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
566	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
567	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
568	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
569	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
570	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
571	     * duplicate, so it is never flagged.
572	     *
573	     * @param owner           the owner being created, with telephone already normalized and
574	     *                        lastName/postcode set
575	     * @param sharesHousehold whether the request opted in to sharing a household
576	     */
577	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
578	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
579	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
580	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
581	    }
