586	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
587	     *
588	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
589	     *             run)
590	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
591	     */
592	    private void rejectCityAtCapacity(String city) {
593	        long ownersInCity = this.clinicService.findAllOwners().stream()
