632	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
633	        LocalDate registrationDate =
634	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
635	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
636	    }
