658	    /**
659	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
660	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
661	     * bulk-signup warning are judged on.
662	     *
663	     * @param registrationDate the create's effective registration date, already rolled onto a business
664	     *                         day by {@link #effectiveRegistrationDate}
665	     * @return the number of existing owners registered on that day
666	     */
667	    private long countRegisteredOn(LocalDate registrationDate) {
668	        return this.clinicService.findAllOwners().stream()
669	            .map(Owner::getRegistrationDate)
670	            .filter(registrationDate::equals)
671	            .count();
672	    }
673	}
